namespace RonSijm.FluidHumidifier.Factories.Lambda;

public class WebFunctionEndpointFactory(string resourceName = null, Action<Humidifier.Lambda.WebFunctionEndpoint> factoryAction = null) : ResourceFactory<Humidifier.Lambda.WebFunctionEndpoint>(resourceName)
{

    internal List<InnerWebFunctionEndpointRevisionWeightFactory> RevisionWeightsFactories { get; set; } = [];

    internal InnerWebFunctionEndpointScalingConfigFactory ScalingConfigFactory { get; set; }

    internal InnerWebFunctionEndpointThrottleConfigFactory ThrottleConfigFactory { get; set; }

    protected override Humidifier.Lambda.WebFunctionEndpoint Create()
    {
        var webFunctionEndpointResult = CreateWebFunctionEndpoint();
        factoryAction?.Invoke(webFunctionEndpointResult);

        return webFunctionEndpointResult;
    }

    private Humidifier.Lambda.WebFunctionEndpoint CreateWebFunctionEndpoint()
    {
        var webFunctionEndpointResult = new Humidifier.Lambda.WebFunctionEndpoint
        {
            GivenName = InputResourceName,
        };

        return webFunctionEndpointResult;
    }
    public override void CreateChildren(Humidifier.Lambda.WebFunctionEndpoint result)
    {
        base.CreateChildren(result);

        result.RevisionWeights = RevisionWeightsFactories.Any() ? RevisionWeightsFactories.Select(x => x.Build()).ToList() : null;
        result.ScalingConfig ??= ScalingConfigFactory?.Build();
        result.ThrottleConfig ??= ThrottleConfigFactory?.Build();
    }

} // End Of Class

